def _normalizar_texto(valor):
    return ' '.join((valor or '').strip().lower().split())


def _montar_chave_aluno(aluno, igreja_id):
    nome = _normalizar_texto(getattr(aluno, 'nome', ''))
    data_nascimento = getattr(aluno, 'data_nascimento', None)
    responsavel = _normalizar_texto(getattr(aluno, 'responsavel', ''))
    telefone = (getattr(aluno, 'telefone_responsavel', '') or '').strip()

    if data_nascimento:
        return (igreja_id, nome, data_nascimento.isoformat())

    if responsavel or telefone:
        return (igreja_id, nome, '', responsavel, telefone)

    return (igreja_id, nome, '', f'fallback-{aluno.pk}')


